@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_get_tests_pagination_followup(
    api_client,
    config_test_data,
    swagger_validator: SwaggerSchemaValidator,
    scenario_case: Dict[str, Any],
):
    """
    Pagination test (conditional):
    - Calls the endpoint; if next_page_token is present and truthy, follows the token using 'page-token' query param.
    - Validates schemas for both initial and follow-up responses.
    - If token isn't present, skips without failure.
    """
    merged = _merge_test_data(config_test_data, scenario_case)

    project_slug = merged.get("project-slug")
    job_number = merged.get("job-number")

    if not project_slug or not job_number:
        pytest.skip("Required path params missing: project-slug and/or job-number not provided in config_test_data or ENDPOINT_TEST_DATA")

    endpoint_path = _build_endpoint_path(project_slug, job_number)

    resp = api_client.get(endpoint_path)
    # Validate initial response as per whatever status code we get
    _validate_response_schema(swagger_validator, resp.status_code, resp)

    # Proceed only if success and token present
    if not (200 <= resp.status_code < 300):
        pytest.skip(f"Initial request did not succeed (status={resp.status_code}); skipping pagination follow-up.")

    try:
        payload = resp.json()
    except Exception:
        pytest.skip("Initial response is not JSON; skipping pagination follow-up.")

    token = payload.get("next_page_token")
    if not token:
        pytest.skip("No next_page_token in response; pagination not applicable for this scenario.")

    # Follow the next page using 'page-token' as described in the spec's property description
    follow_resp = api_client.get(endpoint_path, params={"page-token": token})

    if 200 <= follow_resp.status_code < 300:
        # Validate follow-up success as 200
        _validate_response_schema(swagger_validator, follow_resp.status_code, follow_resp)
    else:
        # For any error, validate against default
        _validate_response_schema(swagger_validator, follow_resp.status_code, follow_resp)


